import { Scene, Rect, Circle, hex } from "retiam";
import { Physics2D } from "retiam/physics";

export default class BouncingBall extends Scene {
  async run() {
    this.composer!.ALWAYS_UPDATE = true;
    const physics = new Physics2D(this, { backend: "planck", gravity: [0, -9.8] });
    const ground = new Rect(10, 0.4).move([0, -3, 0]);
    const ball = new Circle(0.5, { fill: hex("#38BDF8") }).move([0, 3, 0]);
    this.add(ground, ball);
    physics.add(ground, { motion: "static" });
    physics.add(ball, { motion: "dynamic", restitution: 0.75 });
    this.camera.frame([ground, ball], { padding: 0.25 });
    await this.wait(6000);
    physics.destroy();
  }
}
